// Independent auditor PLAY-02 live-database probe of the committed participant view.
import assert from 'node:assert/strict';
import { createHash, randomBytes, randomUUID } from 'node:crypto';
import { service, fixtureId, command, open, counts, cleanup, using } from './apps/match-service/tests/fixtures.mjs';
import { restorePrivateMatch } from './packages/engine-adapter/dist/index.js';
import { canonical } from './packages/engine-adapter/dist/replay.js';
import { encodeViewerProjection } from './packages/contracts/dist/index.js';

const digest = a => createHash('sha256').update('private-match-checkpoint-v1\0').update(a).digest('hex');
const id = fixtureId(), s = service(), s2 = service();
let s3;
const R = { versionsChecked: 0, adapterEqual: 0, concurrentViews: 0, racedViews: 0, invalid: 0, forbidden: 0, pin: 0, tamper: 0, burst: { ok: 0, unavailable: 0 }, refsSeen: new Set(), viewMs: [] };
const stored = () => using('match', async c => (await c.query('SELECT checkpoint,checkpoint_digest,engine_identity,state_version FROM match.matches WHERE match_id=$1', [id])).rows[0]);
const project = (row, playerId) => { const pm = restorePrivateMatch({ archive: row.checkpoint, digest: row.checkpoint_digest }, id); try { return pm.project({ kind: 'participant', playerId }); } finally { pm.dispose(); } };
const hand = (view, p) => view.players.find(x => x.playerId === p).zones.find(z => z.kind === 'hand');
const code = c => e => e?.code === c;
function secretsOf(row) {
  const t = JSON.parse(row.checkpoint).transcript;
  return [t.seed, t.seedCommitment, row.checkpoint_digest, ...t.initial.randomOutcomes.filter(o => String(o.kind).startsWith('identifier')).map(o => String(o.value))];
}
async function play(actor, move, input, cid) {
  const row = await stored(), pm = restorePrivateMatch({ archive: row.checkpoint, digest: row.checkpoint_digest }, id);
  let internal; try { internal = pm.resolveIntent(actor, move, input); } finally { pm.dispose(); }
  return (await s.submit(actor, command(id, cid, Number(row.state_version), move, internal))).receipt;
}
let previousRefs = new Set();
async function checkVersion() {
  const row = await stored(), before = await counts(id), t0 = performance.now();
  const [a, b] = await Promise.all([s.view('p1', { matchId: id }), s2.view('p2', { matchId: id })]);
  R.viewMs.push(Math.round(performance.now() - t0));
  assert.deepEqual(a, project(row, 'p1')); assert.deepEqual(b, project(row, 'p2')); R.adapterEqual += 2;
  assert.equal(a.stateVersion, Number(row.state_version)); assert.equal(b.stateVersion, Number(row.state_version));
  assert.deepEqual(hand(a, 'p2').cards, []); assert.deepEqual(hand(b, 'p1').cards, []);
  assert.equal(hand(a, 'p1').cards.length, hand(a, 'p1').count); assert.equal(hand(b, 'p2').cards.length, hand(b, 'p2').count);
  for (const view of [a, b]) {
    const raw = encodeViewerProjection(view);
    for (const x of secretsOf(row)) assert.equal(raw.includes(x), false, 'secret in committed view');
    for (const ref of raw.match(/vr_[a-f0-9]{64}/g) ?? []) { assert.equal(previousRefs.has(ref), false, 'reference survived a committed revision'); R.refsSeen.add(ref); }
  }
  previousRefs = new Set([a, b].flatMap(v => encodeViewerProjection(v).match(/vr_[a-f0-9]{64}/g) ?? []));
  const many = await Promise.all(Array.from({ length: 16 }, (_, i) => (i % 2 ? s : s2).view(i % 4 < 2 ? 'p1' : 'p2', { matchId: id })));
  for (const v of many) assert.deepEqual(v, v.viewer.playerId === 'p1' ? a : b); R.concurrentViews += many.length;
  assert.deepEqual(await counts(id), before, 'views wrote durable state');
  assert.equal((await stored()).checkpoint, row.checkpoint);
  R.versionsChecked++;
  return { a, b, row };
}
async function setColumns(values) { await using('match', c => c.query('UPDATE match.matches SET checkpoint=$1,checkpoint_digest=$2,engine_identity=$3 WHERE match_id=$4', [values.checkpoint, values.checkpoint_digest, values.engine_identity, id])); }
try {
  await open(s, id);
  let { a } = await checkVersion();
  // Authorization and request validation before any storage access.
  const baseline = await counts(id);
  let getterCalls = 0;
  const invalid = [{ matchId: id, viewer: { kind: 'public' } }, { matchId: id, playerId: 'p2' }, { matchId: id, kind: 'judge' }, { matchId: id, allowPrivate: true }, {}, null, [id], { matchId: 5 }, { matchId: '../' + id }, { matchId: 'a'.repeat(81) },
    { get matchId() { getterCalls++; return id; } }];
  for (const request of invalid) { await assert.rejects(s.view('p1', request), code('INVALID_REQUEST')); R.invalid++; }
  for (const actor of [{ playerId: 'p1' }, '', 'p 1', null, 'x'.repeat(81)]) { await assert.rejects(s.view(actor, { matchId: id }), code('INVALID_REQUEST')); R.invalid++; }
  assert.equal(getterCalls, 0, 'request accessor executed');
  for (const [actor, matchId] of [['outsider', id], ['p1', 'play01-missing-' + randomUUID()], ['p2', 'play01-missing-' + randomUUID()]]) { await assert.rejects(s.view(actor, { matchId }), code('FORBIDDEN')); R.forbidden++; }
  assert.deepEqual(await counts(id), baseline);
  // Reference-driven play through the committed service; each version re-checked.
  let n = 0;
  for (let turn = 0; turn < 4; turn++) {
    const actor = a.turnOwnerId, mine = actor === 'p1' ? a : (await s2.view(actor, { matchId: id }));
    const refs = hand(mine, actor).cards.map(c => c.ref);
    assert.equal((await play(actor, 'putCardIntoInkwell', { cardId: refs[0] }, 'ink-' + n++)).outcome, 'accepted'); ({ a } = await checkVersion());
    const now = actor === 'p1' ? a : await s2.view(actor, { matchId: id });
    assert.equal((await play(actor, 'playCard', { cardId: hand(now, actor).cards[0].ref, cost: 'standard' }, 'play-' + n++)).outcome, 'accepted'); ({ a } = await checkVersion());
    // A stale view's reference is refused by the resolver before any engine call.
    await assert.rejects(play(actor, 'quest', { cardId: refs[1] }, 'stale-ref-' + n++), /Reference rejected/);
    // Views racing a commit return either the old or the new committed state, never a mixture.
    const beforeRow = await stored(), oldA = project(beforeRow, 'p1');
    const [receipt, ...raced] = await Promise.all([play(actor, 'passTurn', {}, 'pass-' + n++), ...Array.from({ length: 6 }, (_, i) => (i % 2 ? s2 : s).view('p1', { matchId: id }))]);
    assert.equal(receipt.outcome, 'accepted');
    const newA = project(await stored(), 'p1');
    for (const v of raced) { assert.ok(JSON.stringify(v) === JSON.stringify(oldA) || JSON.stringify(v) === JSON.stringify(newA), 'raced view mixed states'); R.racedViews++; }
    ({ a } = await checkVersion());
  }
  // Pin and tamper refusals; the original row is restored after each.
  const original = await stored(), goodView = await s.view('p1', { matchId: id });
  await setColumns({ ...original, engine_identity: 'f'.repeat(64) }); await assert.rejects(s.view('p1', { matchId: id }), code('PIN_UNAVAILABLE')); R.pin++;
  await setColumns(original);
  const envelope = JSON.parse(original.checkpoint), forge = mutate => { const e = structuredClone(envelope); mutate(e); const archive = canonical(e); return { ...original, checkpoint: archive, checkpoint_digest: digest(archive) }; };
  const forgeries = [
    forge(e => { e.transcript.seed = randomBytes(32).toString('hex'); }),
    forge(e => { const last = structuredClone(e.transcript.commands.at(-1)); last.command.move = 'manualSetLore'; last.command.input = { amount: 20 }; e.transcript.commands.push(last); }),
    forge(e => { e.transcript.final.status.winner = 'p2'; e.transcript.final.status.ended = true; }),
    forge(e => { e.transcript.commands.pop(); }),
    forge(e => { e.matchId = 'other-' + id; }),
    { ...original, checkpoint: original.checkpoint.replace('"p1"', '"p2"') },
  ];
  for (const f of forgeries) { await setColumns(f); await assert.rejects(s.view('p1', { matchId: id }), e => e?.code === 'UNAVAILABLE'); R.tamper++; await setColumns(original); }
  assert.deepEqual(await s.view('p1', { matchId: id }), goodView, 'view changed after restoring the original row');
  // Burst beyond the bounded queue fails closed with fixed codes and writes nothing.
  const before = await counts(id);
  const burst = await Promise.allSettled(Array.from({ length: 48 }, () => s.view('p1', { matchId: id })));
  for (const r of burst) { if (r.status === 'fulfilled') { assert.deepEqual(r.value, goodView); R.burst.ok++; } else { assert.equal(r.reason?.code, 'UNAVAILABLE'); R.burst.unavailable++; } }
  assert.deepEqual(await counts(id), before);
  // Restart reproduces; terminal state stays hand-private for both participants.
  s3 = service(); assert.deepEqual(await s3.view('p1', { matchId: id }), goodView);
  const end = await s3.submit('p2', command(id, 'concede', Number((await stored()).state_version), 'concede', {}));
  assert.equal(end.receipt.outcome, 'accepted');
  const [ea, eb] = await Promise.all([s3.view('p1', { matchId: id }), s3.view('p2', { matchId: id })]);
  assert.equal(ea.ended, true); assert.equal(ea.winner, 'p1'); assert.equal(eb.winner, 'p1');
  assert.deepEqual(hand(ea, 'p2').cards, []); assert.deepEqual(hand(eb, 'p1').cards, []);
  assert.deepEqual(ea.commands, []);
  const finalRow = await stored(); for (const x of secretsOf(finalRow)) assert.equal(JSON.stringify([ea, eb]).includes(x), false);
  console.log(JSON.stringify({ ...R, refsSeen: R.refsSeen.size, finalVersion: Number(finalRow.state_version), endedCommands: ea.commands }));
  console.log('PASS auditor PLAY-02 live service probe: committed participant views equal the adapter projection of the stored checkpoint at every version, hide the opponent hand, carry no seed/commitment/digest/instance identity, rotate references each commit, are byte-stable under 16-way concurrency and write nothing; views racing a commit return exactly the old or new state; malformed/escalating requests are INVALID_REQUEST without running accessors; outsiders and missing matches are both FORBIDDEN; identity pin mismatch is PIN_UNAVAILABLE; six re-digested or raw checkpoint forgeries fail closed and recovery is exact after restoration; queue overflow fails closed with fixed codes; restart reproduces; terminal views keep hands private');
} finally { await s.close(); await s2.close(); await s3?.close(); await cleanup(id); }
